using Godot;using Hmi.Core;using Hmi.GodotAdapter;using System;using System.Text.Json;
public partial class StationaryFacingProbe:Node
{
 int checks;bool done;void C(bool v,string why){checks++;if(!v)throw new Exception(why);}
 GameSimulation Sim(){var c=JsonSerializer.Deserialize<GameContent>(FileAccess.GetFileAsString("res://content/gameplay.json"),new JsonSerializerOptions{PropertyNameCaseInsensitive=true});var s=new GameSimulation(c);s.StartRun("crit",1030);return s;}
 public override void _Ready(){try{Run();done=true;}catch(Exception e){GD.PushError(e.ToString());GetTree().Quit(1);}}
 public override void _Process(double d){if(done)GetTree().Quit();}
 void Run(){var s=Sim();var f=new StationaryLaunchFacing();f.Begin(s,true);f.Input(0,0);C(!f.Held,"no launch no aim");for(int i=0;i<61;i++){f.Begin(s,true);f.Input(0,0);s.Step();f.CaptureStep(s);}C(f.Held&&f.Accepted==1,"first natural stationary launch");float yaw=f.Yaw;f.CaptureStep(s);C(f.Accepted==1,"duplicate buffer no replay");var o=new object();f.Attach(o);C(f.Held,"first presenter keeps first capture");f.Attach(new object());C(!f.Held,"replacement clears held");f.CaptureStep(s);C(!f.Held,"owner replacement no repeated buffer");f.AcceptDirection(1,0);f.ClearPresentation();f.CaptureStep(s);C(!f.Held,"focus clear retains dedup");f.AcceptDirection(1,0);f.Begin(s,true);C(f.Held&&!f.Sampled,"noStep held retained unsampled");f.Input(1,0);C(!f.Held,"nonzero intent clears independent of velocity");C(!f.AcceptDirection(0,0)&&!f.AcceptDirection(float.NaN,1),"invalid vector rejects");
 var moving=Sim();var m=new StationaryLaunchFacing();for(int i=0;i<61;i++){m.Begin(moving,true);m.Input(1,0);moving.Step();m.CaptureStep(moving);}C(!m.Held&&m.MovingDrops==1,"moving launch not stored although Core movement not queued (wall analogue)");m.Begin(moving,true);m.Input(0,0);m.CaptureStep(moving);C(!m.Held,"stop cannot replay moving launch");
 f.AcceptDirection(0,1);s.Enqueue(new GameCommand(CommandKind.Pause,flag:true,runToken:s.RunToken,wave:s.Wave));s.Step();f.Begin(s,true);f.CaptureStep(s);C(s.Paused&&f.Held,"actual pause keeps held");f.Begin(s,false);C(!f.Held,"actual hidden clears");f.AcceptDirection(1,0);s.PrepareRun("crit",1031);f.Begin(s,true);C(!f.Held,"new scope clears");
 var resumed=Sim();var rf=new StationaryLaunchFacing();for(int i=0;i<60;i++){rf.Begin(resumed,true);rf.Input(0,0);resumed.Step();rf.CaptureStep(resumed);}resumed.Enqueue(new GameCommand(CommandKind.Pause,flag:true,runToken:resumed.RunToken,wave:resumed.Wave));resumed.Step();rf.Begin(resumed,true);C(resumed.Paused&&!rf.InputKnown,"pause before first launch invalid input");resumed.Enqueue(new GameCommand(CommandKind.Pause,flag:false,runToken:resumed.RunToken,wave:resumed.Wave));resumed.Step();rf.CaptureStep(resumed);C(!rf.Held&&rf.UnknownInputDrops==1,"real first Launch in resume Step rejected unknown input");rf.Input(0,0);rf.CaptureStep(resumed);C(!rf.Held&&rf.Accepted==0,"resume Launch never backlogged after fresh zero input");
 foreach(float dt in new[]{1f/30,1f/60,1f/120,1f/144,1f/15,.25f})foreach(float target in new[]{-MathF.PI,MathF.PI,.5f,-.5f}){float next=StationaryLaunchFacing.Turn(0,target,dt);C(Math.Abs(next)<=StationaryLaunchFacing.Rate*Math.Min(dt,.25f)+1e-6f,"hard angle cap");}C(StationaryLaunchFacing.Turn(0,MathF.PI,1f/60)>0&&StationaryLaunchFacing.Turn(0,-MathF.PI,1f/60)>0,"deterministic pi sign");C(StationaryLaunchFacing.Turn(.3f,2,0)==.3f&&StationaryLaunchFacing.Turn(.3f,2,float.NaN)==.3f,"invalid time freeze");
 foreach(int hz in new[]{30,60,120,144}){double acc=0;float angle=0;int sampled=0;for(int frame=0;frame<hz/2;frame++){acc+=1.0/hz;bool step=false;while(acc+1e-12>=1.0/60){acc-=1.0/60;step=true;}float before=angle;if(step)sampled++;angle=StationaryLaunchFacing.Turn(angle,MathF.PI,1f/hz);C(angle-before<=StationaryLaunchFacing.Rate/hz+1e-6f&&angle>=before,"each render bounded including noStep");}GD.Print($"FACING_RATE hz={hz} seconds=.5 sampledRenders={sampled} degrees={angle*180/MathF.PI}");C(Math.Abs(angle-120*MathF.PI/180)<.0001f,"all refresh rates same real .5s turn without delta accumulation");}
 GD.Print($"STATIONARY_FACING_PASS {checks}");}
}
